insert into abm_senales (cuenta_id,tipo,detalle,peso,origen,fecha,caduca_at) select id::uuid,tipo,det,peso,'google_maps',current_date,current_date+365
from (values
('4d75dc48-2f8d-43a3-81cd-c11f4ddf445e','resena_mala','Curso anual pagado sin derecho a reembolso, trato elitista y respuestas sarcásticas a las preguntas de los alumnos.',10),
('c8118aa0-f41d-45bd-8cce-c44356d995c4','resena_mala','Le negaron tres veces personalizar un jersey diciendo que estaba agotado "sin cerciorarse", y luego resultó que sí había; también trabajos de grabado mal entregados.',12),
('8ecd3e9b-b2b5-445c-9731-ffa57404014e','resena_mala','"Quedaron formalmente que tenían los trajes y nada que ver": promesa de existencia que no se cumple, más caja con mala actitud y promociones poco claras.',12),
('7544538c-da54-4a58-aa03-a42d7b246c26','resena_mala','"Nunca tienen mis pedidos completos"; hoy varias reseñas dicen que la tienda ya no existe.',12),
('491d16f7-b28f-4894-a3c9-ab62a0b8cc47','resena_mala','"Entregan rápido cuando lo tienen en inventario"; cuando no, falta claridad y nadie resuelve el problema de fabricación.',12),
('e71cb596-6af7-4abf-89a4-87de83c7a762','resena_mala','Le mandaron un 22.5 en vez del 22 y "borraron la numeración y la taparon con una etiqueta para que no me diera cuenta".',12),
('b16faded-9461-49f7-abcb-2348e64294c3','resena_mala','"No me respetaron una ropa que me apartaron", poca variedad y horarios de Google que no coinciden con los reales.',12),
('6bb2ea71-6bd5-4f65-8b24-79071fba8e1f','resena_mala','Falta variedad de tallas y precios percibidos como altos, aunque la atención es buena.',12),
('c748b6ba-6e22-48ed-8d57-c8139c5bcdac','resena_mala','"No hay modelos, números" en tienda; y proveedores que se quejan de que la razón social paga tarde.',12),
('be4f2de3-c59d-4877-81cf-e060e3493ba9','resena_mala','"No tienen de todas las tallas del calzado que venden" y cierran antes del horario publicado.',12),
('8ab8600a-401a-4047-86c7-9c8d0d218005','resena_mala','"Me cobraron 1000 más y no han atendido mi reclamación"; el mismo par cambiado dos veces por el mismo defecto y sin devolución de dinero.',10),
('a6654ca0-23ed-4365-9a35-d875cf836e62','resena_mala','"Sus modelos se repiten mucho": poca rotación de surtido y precio percibido como elevado para la calidad.',12),
('6c91870d-2f65-4312-8d53-8f2c823579a1','resena_mala','"No me la cambiaba porque sus jefes le dijeron que no había cambios porque ya no le salía el inventario": el descuadre de inventario bloquea el cambio al cliente.',12),
('3a6db856-f6fa-49c4-8d0a-7368459af7d0','resena_mala','"Segunda vez que no tienen cambio": 20 minutos para dar el cambio en efectivo y 10 más para devolver el dinero de una devolución.',10),
('1f0e68d7-0cbc-4e63-8dae-b016d1ad012c','resena_mala','"Ya le hace falta más variedad de calzado": surtido corto y muy orientado a lo formal.',12),
('acba8fbb-7208-4e3b-bd1b-a8c0fd26c252','resena_mala','Sin el ticket físico el gerente "no podía hacer nada" para cambiar una prenda con etiquetas comprada ahí semanas antes; camisas a medida entregadas mal dos veces.',10),
('9d89eb04-7f86-421b-ace3-ef5996a85618','resena_mala','"Mala logística y tallas" en la venta de jerseys, con empleados apartando tallas para revenderlas; guardias presionando al cliente.',12),
('040b2cc4-5442-4ca8-89f8-55aa18bbb07b','resena_mala','"No tenían los pares en tienda, sólo uno de cada uno"; en línea le avisaron tarde que un modelo ya no estaba disponible después de haber depositado.',12),
('7e118cf3-e6db-41b7-8b91-61041eda7ee0','resena_mala','Falta variedad y personal poco atento.',12),
('2a99dfa6-dec4-4f1a-893c-47bc5905abd3','resena_mala','"Siempre tienen los mismos modelos": falta de variedad y de rotación entre visitas separadas por meses.',12),
('81a3154e-7d39-4ba2-b402-febf79a5de75','resena_mala','"Me cobró mal, volvió a hacer la cuenta" en caja; además cambios negados por prenda usada medio día y baja de calidad percibida.',10),
('77e367cb-118a-4c2c-bd95-763608b071a7','resena_mala','Un empleado filtraba información de existencias a familiares para competir; y un pedido de 2 pares del que solo llegó uno, sin respuesta de servicio al cliente.',12),
('3abf7b81-808c-419a-924b-4d9bf0fc935e','resena_mala','El día de la boda faltó el cintillo del vestido: entregaron el paquete incompleto y sellado; vestidos entregados con grapas, alfileres, rotos o sucios.',12),
('7081b28e-c76f-4d7e-9f9f-c691196d064e','resena_mala','Pocos modelos y casi sin descuentos.',12),
('01cd152d-25c7-425c-9358-1d9c3255f442','resena_mala','Prometieron cambio de una silla defectuosa y "la persona que me la vendió ya no trabaja aquí": nadie resuelve ni devuelve la llamada.',10),
('11536742-9071-4853-aa7b-9081882aa800','resena_mala','Poco producto disponible, servicio lento en caja (30 minutos para pagar) y ficha de Google desactualizada.',12),
('9aeeac7d-f3d8-45b3-83eb-a449fa3ce408','resena_mala','Suelas que se despegan a la primera puesta y cambio de talla negado en la venta en línea.',10),
('7a2065cb-e45f-42be-99e3-ae7886c73a88','resena_mala','"Compré tres pares y uno me lo dieron de otra talla" y calzado al que "le borraron la talla"; la encargada presiona para comprar rápido.',12),
('6fcb7904-a90b-49cf-9cf7-08a2eb034efd','resena_mala','"No hacen cambios de talla ni presentando el ticket" y dicen condiciones que no estaban estipuladas al comprar.',10),
('106b56c3-bf8d-4aab-8edc-b1b643773900','resena_mala','Le dijeron 3 años de garantía y luego "esa maleta tenía solo 1"; no contestan el teléfono.',10),
('4adc85cb-c6c8-4e49-9801-06027c8fd35a','resena_mala','"No tienen inventario, puro rezagado", y trajes dejados a arreglos que se entregan arrugados y en mal estado.',12),
('960360d3-fbea-46e2-b370-f0f5810d68cf','resena_mala','"Me hizo falta producto y no se hicieron responsables"; otro cliente depositó su pedido y nunca recibió guía ni respuesta.',12),
('7cff4aca-983b-481b-9659-3b738f7322d7','resena_mala','"Publicidad engañosa en su tienda en línea": pidió un traje de baño y le mandaron otra prenda, con política de devolución engorrosa y atención a clientes grosera.',12),
('4e64d1c3-a61a-4892-9de2-a385c4b3d452','resena_mala','Pagaron los maniquíes en agosto y nunca los entregaron ni contestaron llamadas ni correos; poco surtido.',10),
('32b85089-dfe4-4011-9f88-7c7b56b7ce71','resena_mala','"Me cobraron dos veces dos pantalones" y la garantía de un mes no se hizo válida por un cierre descosido.',10),
('0df00090-c4f5-4bdf-89ed-0d9ecaf216c3','resena_mala','"Me hicieron dar vuelta diciendo que sí había tallas", modelos que ya no tenían al momento del cambio y guías de envío que nunca se depositan.',12),
('927ce04c-c398-4ccc-8b2f-e693923bc2c2','resena_mala','"Para los que compraban tallas extra ya no hay nada: la talla más grande es 31"; además un caso de clonación de tarjeta en la tienda.',12),
('7ed5d9c1-c0bf-4d96-a02f-6a8f76509ff5','resena_mala','"No hay probadores en muchas tiendas y en la mayoría no aceptan tarjetas"; los precios ya no son de mayoreo.',10),
('88f50e34-65c5-4aae-878e-bc41e96a82c7','resena_mala','"No hay probadores en muchas tiendas y en la mayoría NO aceptan tarjetas", y los precios ya no son de mayoreo.',10),
('ebe3a30c-624f-4add-b235-cc4dfed1b33b','resena_mala','"El cobro se hizo al 100% desde que se hizo el pedido" y semanas después de vencido el plazo siguen sin entregar; pedidos incompletos sin solución.',10),
('668d732e-0b87-48e5-b7d3-a497d691cac2','resena_mala','"Por problemas con la terminal terminé pagando dos veces el importe" y nadie le respondió; además le entregaron dos tacones de número distinto.',10),
('5ad13e1d-c0b3-4d8c-8c38-57ffc05ba56d','resena_mala','Trato descortés al fallar el pago con tarjeta de un cliente frecuente, y "ya casi no hay variedad".',10),
('bea553ac-1dfd-4e6b-81bf-241c569490d0','resena_mala','Anillo a la medida pagado 50% por anticipado con 4 meses de retraso sobre la fecha prometida; el anticipo quedó sin control ni seguimiento.',10),
('3bd99d74-bf37-4974-b4f9-a004aeb877da','resena_mala','"Les pagué un collar y luego me salieron que no lo tenían": vendieron pieza sin existencia, el pedido nunca llegó y tampoco hubo reembolso.',12),
('5ae9834f-c13c-4f0b-aeca-3919fa3bf127','resena_mala','Garantía y mantenimiento negados por no traer el recibo físico, y baño de oro sin cobertura; incertidumbre sobre el estado del pedido.',10),
('5a5acafb-716e-4629-8f40-fb4ab5a8c042','resena_mala','Devolución autorizada que lleva casi un mes sin pagarse por falta de documentos, y una pieza devuelta rayada del taller.',10)
) as v(id,tipo,det,peso);
with s as (select cuenta_id, sum(peso) peso from abm_senales
   where coalesce(vigente,true) and (caduca_at is null or caduca_at>=current_date)
     and (fecha is null or fecha > current_date-180) and tipo<>'sitio_caido' group by cuenta_id)
update abm_cuentas c set dolor = least(50,
    (case when c.plataforma_web ~* 'shopify|woo|vtex|wix|tiendanube|magento|prestashop|squarespace' and coalesce(c.sucursales,2)>=2 then 16 else 0 end)
  + (case when c.sitio_http=0 or c.sitio_http>=400 then 12 else 0 end)
  + (case when c.sitio_carrito is false then 8 else 0 end)
  + (case when c.google_rating<4.5 and coalesce(c.sucursales,0)>=3 then 10 else 0 end)
  + coalesce((select peso from s where s.cuenta_id=c.id),0));
update abm_cuentas set puntaje = encaje + dolor;